import{_ as o,o as t,c as a,a3 as l}from"./chunks/framework.Dq9u6otn.js";const u=JSON.parse('{"title":"组件库介绍","description":"","frontmatter":{},"headers":[],"relativePath":"uniapp/guide.md","filePath":"uniapp/guide.md"}'),r={name:"uniapp/guide.md"};function i(d,e,c,s,n,p){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="组件库介绍" tabindex="-1">组件库介绍 <a class="header-anchor" href="#组件库介绍" aria-label="Permalink to &quot;组件库介绍&quot;">​</a></h1><p>coolui-scroller 是一个专注小程序<strong>下拉刷新 / 上拉加载 / 长列表</strong>的组件库。本页是 <strong>uni-app 版</strong>（npm 包 <code>coolui-scroller-uni</code>）的介绍；原生微信小程序版的介绍见 <a href="/coolui-scroller/v4/native/guide.html">另一平台文档</a>，两套实现组件能力与配置项一致。</p><p><a style="display:inline-block;" href="https://github.com/wzs28150/coolui-scroller"><img src="https://img.shields.io/github/stars/wzs28150/coolui-scroller?style=social" alt="Stars"></a></p><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><h3 id="初衷" tabindex="-1">初衷 <a class="header-anchor" href="#初衷" aria-label="Permalink to &quot;初衷&quot;">​</a></h3><p>本来写这个组件的初衷，是在我写了一个小程序之后，发现小程序如果要实现下拉刷新、上拉加载有两种方式:</p><ol><li>页面级的：利用页面 Page 里提供的方法。下拉虽说是那个东西但是它只有下拉三个点的动画效果而且只能显示在头部就很尴尬。很多时候一个列表的头部往往会有一些组件比如搜索、分类导航等等。所以往往列表都是局部的非页面级的。这时候下拉时动画出现在最顶部就显得很突兀。</li><li>组件级的：利用 scroll-view。 但是当你打开 scroll-view 官方文档时，映入眼帘的是一列列的参数属性方法。要完全弄懂里面的内容，恐怕你得上手写写，挨个试试里面的参数和方法才行。而对于下拉刷新这个效果文档上有个简易的 demo 可寻。上拉加载也只有 bindscrolltolower 这么个方法和 lower-threshold 阈值。所以要实现起来完全还得靠自己。</li></ol><p>所以在写项目的最后我把页面的列表下拉刷新,上拉加载进行了初步的封装。单独拿出来方便之后重复使用。所以有了起初的 1.0 版。</p><h3 id="发展" tabindex="-1">发展 <a class="header-anchor" href="#发展" aria-label="Permalink to &quot;发展&quot;">​</a></h3><h4 id="v2-0" tabindex="-1">V2.0 <a class="header-anchor" href="#v2-0" aria-label="Permalink to &quot;V2.0&quot;">​</a></h4><p>scroll-view 组件初期并没有那么多配置,所以 1.0 实现的效果很有限。 后来随着官方 scroll-view 组件的不断的更新。增加了很多新的属性和事件使得下拉可以自定义起来。虽然也有很多地方不尽人意，但是可玩度还是有很多的。所以又升级了 2.0 版增加了很多下拉的自定义动画效果和上拉加载的效果。</p><p>2.0 版组件还是围绕着 scroll-view,写法上只有一个封装好的 scroller 组件。内置了一个基础的下拉效果。提供下拉的插槽位置。并给出了几个有趣的下拉效果 demo(如：天猫效果、京东小人效果)让下拉又有了更多的可能性;配置上也考虑了很多增加了列表为空时的设置上拉加载的配置。整个配置就是一个 Obj,细化到文字、背景。</p><h4 id="v3-0" tabindex="-1">V3.0 <a class="header-anchor" href="#v3-0" aria-label="Permalink to &quot;V3.0&quot;">​</a></h4><p>3.0 版打算把之前各个部分的插槽进行细化及拆分。并新增空列表插槽及组件、初次进入程序时的手势提示组件、顶部插槽及顶部插槽可用的组件(如：搜索组件、分类组件、下拉筛选组件)。</p><p>除了组件的变化外，核心列表准备加入长列表处理，解决数据量大时列表会出现的问题(如：setData 加载大数据的耗时高、列表渲染出来的 Dom 结构多、占用的内存高，造成页面被系统回收的概率变大等)。起初想以官方给出的 recycle-view 组件进行扩展。但是使用中，遇到很多坑及不方便之处。最让我接受不了的是需要设置 itemSize 这个方法。当我在不确定列表元素宽高的时候就很难设置。后来经过大量的思考和查资料及尝试。决定采用知乎上 daisy 提出的长列表解决方案。</p><h3 id="v3-0-版" tabindex="-1">v3.0 版 <a class="header-anchor" href="#v3-0-版" aria-label="Permalink to &quot;v3.0 版&quot;">​</a></h3><ol><li>基于小程序原生组件 scroll-view 的扩展与封装,实现简单的上拉加载下拉刷新</li><li>扩展下拉刷新动画，有灵感的朋友可以丰富更多下拉动画</li><li>上传至 npm 包可安装下载并 npm 构建</li><li>修改参数配置使组件使用更便捷</li><li>增加加载插槽可以自定义加载更多样式</li><li>增加多组件配合使列表功能更丰富</li></ol><h2 id="v4-0-版" tabindex="-1">v4.0 版 <a class="header-anchor" href="#v4-0-版" aria-label="Permalink to &quot;v4.0 版&quot;">​</a></h2><p>v4.0.0 有两条主线：<strong>长列表窗口化</strong>，以及<strong>同仓维护的原生 + uni-app 双版本</strong>。</p><h3 id="长列表窗口化" tabindex="-1">长列表窗口化 <a class="header-anchor" href="#长列表窗口化" aria-label="Permalink to &quot;长列表窗口化&quot;">​</a></h3><p>v3 的长列表是「每一页都保留一个页组件实例，滚出视口后把列表项换成占位」。页数一多，<strong>页结构本身</strong>也会成为卡顿来源。v4.0.0 把「窗口」从 item 层扩展到 page 层：</p><ul><li>只真实渲染<strong>窗口内</strong>的页（当前可见页 ± 相邻页），窗口外折叠为<strong>上下两个占位块</strong>；</li><li>页高定位改为「滚动距离 + 页高前缀和二分」，复杂度 O(log N)，不再依赖 IntersectionObserver；</li><li>未测量的页用「已测量页的平均值」估算，滚过后回填并自动收敛。</li></ul><p>在 uni-app 版里，这部分由窗口化容器 <a href="/coolui-scroller/v4/uniapp/components/longlist.html"><code>coolui-scroller-longlist</code></a> 承担（<code>pages</code> 二维分页数据 + 把 <code>scroller</code> 的 <code>@scroll</code> 传进来即可）。</p><h2 id="uni-app-版" tabindex="-1">uni-app 版 <a class="header-anchor" href="#uni-app-版" aria-label="Permalink to &quot;uni-app 版&quot;">​</a></h2><p>本页所在版本即为 uni-app 版，它按 Vue 的习惯重新实现，与原生微信小程序版的差异集中在写法上：</p><table tabindex="0"><thead><tr><th>项</th><th>原生微信小程序版</th><th>uni-app 版</th></tr></thead><tbody><tr><td>组件通信</td><td>小程序 <code>relations</code> 关联父子组件</td><td>Vue <code>provide/inject</code></td></tr><tr><td>事件</td><td><code>bind:xxx</code></td><td><code>@xxx</code>；受控属性 <code>@update:propName</code>（可写 <code>v-model:xxx</code>）</td></tr><tr><td>引入方式</td><td><code>usingComponents</code></td><td>easycom 免 import，也支持全局注册 / 页面内局部引入</td></tr><tr><td>长列表</td><td><code>scroll-page</code> 窗口化渲染</td><td>新增 <code>coolui-scroller-longlist</code>（窗口化容器，推荐）</td></tr><tr><td>类型</td><td>—</td><td>组件用 <code>&lt;script setup lang=&quot;ts&quot;&gt;</code>，公共类型集中在 <code>types.d.ts</code></td></tr><tr><td>样式定制</td><td><code>externalClasses</code></td><td><code>virtualHost + apply-shared</code>，页面里用 <code>:deep()</code> 覆盖</td></tr></tbody></table><ul><li>一套代码编译到微信 / 支付宝 / 百度 / 字节 / QQ 小程序以及 H5、App 端；</li><li>保留字属性改名：search 的 <code>key</code> → <code>keyword</code>、handtip 的 <code>key</code> → <code>storageKey</code>；</li><li>各端差异（H5 内置导航栏占高、插槽与样式作用域等）见<a href="/coolui-scroller/v4/uniapp/platform-diff.html">与原生微信小程序版的差异</a>。</li></ul><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li><strong>安装与引入</strong>：<a href="/coolui-scroller/v4/uniapp/install.html">uni-app 版安装与引入</a> —— npm 安装、easycom 配置、三种引入方式</li><li><strong>快速开始</strong>：<a href="/coolui-scroller/v4/uniapp/quickstart.html">快速开始</a> —— 最小可运行的下拉刷新 + 上拉加载</li><li><strong>挑组件</strong>：<a href="/coolui-scroller/v4/uniapp/components/">组件总览 / 命名对照</a> —— 与原生微信小程序版的标签对照表</li><li><strong>看示例</strong>：<a href="/coolui-scroller/v4/case/">示例 demo</a> —— 扫码预览与源码工程</li><li><strong>换平台</strong>：如果项目是微信小程序原生项目，请看<a href="/coolui-scroller/v4/native/install.html">原生微信小程序版文档</a>，或用站点顶部的平台切换器</li></ul>',29)])])}const m=o(r,[["render",i]]);export{u as __pageData,m as default};
